const data = raw.body ? JSON.parse(raw.body) : raw;

// Kommuner (VG) + Län (hela Sverige) — lägg till fler vid behov
const geografi = {
  "1401":"Härryda","1402":"Partille","1407":"Öckerö","1415":"Stenungsund",
  "1419":"Tjörn","1421":"Orust","1427":"Sotenäs","1430":"Munkedal",
