      kpi:         kpi,
      bransch:     "alla",
      kon:         "totalt",
      varde:       varde,
      enhet:       enhet
    }
  });
}
return rows;

// Normalisera AF-svaret (redan platt JSON från /af-endpointen i scb-mcp-v2)
const raw = $input.first().json;
const values = raw.values || [];

const indikator = $('Loop Over Items').first().json;
const kpi   = indikator.kpi;
const kalla = indikator.kalla;
const enhet = indikator.enhet;

const rows = [];
for (const item of values) {
  if (item.value === null || item.value === undefined) continue;

  const [arStr, manadStr] = String(item.period || "").split("-");
  const ar    = parseInt(arStr, 10);
  const manad = manadStr ? parseInt(manadStr, 10) : null;

  rows.push({
    json: {
      kommun_kod:  item.kommun_kod,
      kommun_namn: item.kommun_namn,
      ar:          Number.isNaN(ar) ? null : ar,
      manad:       manad,
      kalla:       kalla,
      kpi:         kpi,
      bransch:     "alla",
      kon:         "totalt",
      varde:       item.value,
      enhet:       item.enhet || enhet
    }
  });
}
return rows;
